def append_unit_first(values: np.ndarray, rows: list[dict]) -> np.ndarray:
    values = np.asarray(values, dtype=np.float32)
    if not np.isfinite(values).all():
        raise ValueError("values must be finite")
    baseline = _unit_baselines(values, rows)
    return np.concatenate((values, values - baseline[:, None, :]), axis=2).astype(np.float32)

def cap_rul(rul, rmax: float) -> np.ndarray:
    """§7.3 / 白皮书附录 B 式 1: y_rul = min(label.rul, Rmax), float32。

    - 分段线性: 早期(rul > Rmax)恒 Rmax, 之后随 t 线性下降 —— min 即该折线;
    - NaN 原样透传(删失单元, §6.6-1), 由调用方决定剔除口径(附录 X2-6);
    - rmax 必须为有限正数(Rmax 由训练集寿命分布统计确定, §7.3)。
    """
    rmax = float(rmax)
    if not np.isfinite(rmax) or rmax <= 0:
        raise ValueError(f"Rmax 必须为有限正数(interfaces.md §7.3), 得到: {rmax!r}")
    arr = np.asarray(rul, dtype=np.float64)
    return np.minimum(arr, rmax).astype(np.float32)

def _unit_baselines(values: np.ndarray, rows: list[dict]) -> np.ndarray:
    values = np.asarray(values, dtype=np.float32)
    if values.ndim != 3 or len(rows) != len(values):
        raise ValueError("values and rows must align")
    first: dict[str, tuple[float, int]] = {}
    for index, row in enumerate(rows):
        key = str(row["unit_id"])
        t_end = float(row.get("t_end", index))
        if key not in first or t_end < first[key][0]:
            first[key] = (t_end, index)
    baseline = np.empty((len(rows), values.shape[2]), dtype=np.float32)
    for index, row in enumerate(rows):
        baseline[index] = values[first[str(row["unit_id"])][1], 0, :]
    return baseline

def append_unit_first(values: np.ndarray, rows: list[dict]) -> np.ndarray:
    values = np.asarray(values, dtype=np.float32)
    if not np.isfinite(values).all():
        raise ValueError("values must be finite")
    baseline = _unit_baselines(values, rows)
    return np.concatenate((values, values - baseline[:, None, :]), axis=2).astype(np.float32)

def predict_models_unit_first(models, sequences, rows, center, scale, device_name):
    normalized = ((np.asarray(sequences, dtype=np.float32) - center[None, None, :]) / scale[None, None, :]).astype(np.float32)
    values = torch.from_numpy(np.transpose(append_unit_first(normalized, rows), (0, 2, 1)))
    outputs = []
    device = torch.device(device_name)
    for model, tmax in models:
        with torch.no_grad():
            outputs.append(model(values.to(device), torch.from_numpy(b._age(rows, tmax)).to(device)).cpu().numpy())
    return np.median(np.stack(outputs, axis=0), axis=0).astype(np.float32)

def normalize(X: np.ndarray, channels: list[str], stats: dict) -> np.ndarray:
    mean = np.array([stats[c]["mean"] for c in channels], dtype=np.float64)
    std = np.array([stats[c]["std"] for c in channels], dtype=np.float64)
    std_eff = np.where(std > STD_EPS, std, 1.0)   # 常量通道: 以 1.0 代入 ⇒ 归一后恒 0(X2-7)
    return ((X - mean) / std_eff).astype(np.float32)

def _age(rows: list[dict[str, Any]], tmax: float) -> np.ndarray:
    return np.asarray(
        [float(row.get("t_end", 0.0)) / max(float(tmax), 1e-9) for row in rows],
        dtype=np.float32,
    )

def project(prediction: np.ndarray, rows: list[dict[str, Any]], mode: str) -> np.ndarray:
    out = np.asarray(prediction, dtype=np.float32).copy()
    by_unit: dict[str, list[int]] = {}
    for index, row in enumerate(rows):
        by_unit.setdefault(str(row["unit_id"]), []).append(index)
    for indices in by_unit.values():
        order = sorted(indices, key=lambda index: float(rows[index].get("t_end", index)))
        if mode == "causal_running_min":
            running = 1.0
            for index in order:
                running = min(running, float(out[index]))
                out[index] = running
        elif mode == "isotonic_nonincreasing":
            values = out[order].astype(np.float64)
            levels: list[float] = []
            counts: list[int] = []
            for value in values:
                levels.append(float(value))
                counts.append(1)
                while len(levels) >= 2 and levels[-2] < levels[-1]:
                    total = counts[-2] + counts[-1]
                    levels[-2] = (counts[-2] * levels[-2] + counts[-1] * levels[-1]) / total
                    counts[-2] = total
                    levels.pop()
                    counts.pop()
            out[order] = np.clip(np.repeat(levels, counts), 0.0, 1.0).astype(np.float32)
        else:
            raise ValueError(mode)
    return np.clip(out, 0.0, 1.0)

def pava(values: np.ndarray) -> np.ndarray:
    levels, weights = [], []
    for value in np.asarray(values, dtype=np.float64):
        levels.append(float(value)); weights.append(1)
        while len(levels) >= 2 and levels[-2] < levels[-1]:
            total = weights[-2] + weights[-1]
            levels[-2] = (weights[-2] * levels[-2] + weights[-1] * levels[-1]) / total
            weights[-2] = total; levels.pop(); weights.pop()
    return np.repeat(np.asarray(levels, dtype=np.float32), np.asarray(weights, dtype=np.int64))

def project(pred: np.ndarray, rows: list[dict], mode: str) -> np.ndarray:
    if mode == "raw":
        return np.asarray(pred, dtype=np.float32)
    out = np.asarray(pred, dtype=np.float32).copy()
    by_unit: dict[str, list[int]] = {}
    for i, row in enumerate(rows):
        by_unit.setdefault(str(row.get("unit_id", "")), []).append(i)
    for idx in by_unit.values():
        order = sorted(idx, key=lambda i: float(rows[i].get("t_end", i)))
        if mode == "isotonic_nonincreasing":
            out[order] = np.clip(pava(out[order]), 0.0, 1.0)
        elif mode == "causal_running_min":
            running = 1.0
            for i in order:
                running = min(running, float(out[i])); out[i] = running
        else:
            raise ValueError(mode)
    return out

def build_index(unit_id: str, dataset_id: str, domain: str, split: str,
                t_end_values, window_id_prefix: str = "") -> list[dict]:
    """§7.1 meta.index「每窗一条」: 六字段字典列表, 顺序与窗一致。

    window_id_prefix(附录 AJ2-6, 0711-05 追加): 缺省空串 = X2-5 字面(输出与
    0710-04 逐字节相同); 域限定混池传 `f"{dataset_id}/"` ⇒ window_id 取超集文法
    `<dataset_id>/<unit_id>:w<序:05d>`(全仓唯一由 §1.1 dataset_id 唯一性兜底);
    `unit_id` 字段本身**不**加前缀(§7.1 六字段语义不变)。
    """
    if domain not in DOMAINS:
        raise ValueError(f"domain 必须 ∈ {DOMAINS}(§7.5), 得到: {domain!r}")
    if split not in SPLITS:
        raise ValueError(f"split 必须 ∈ {SPLITS}(§7.5), 得到: {split!r}")
    rows = []
    for k, t_end in enumerate(np.asarray(t_end_values, dtype=np.float64), start=1):
        rows.append({
            "window_id": window_id_prefix + WINDOW_ID_FMT.format(unit_id=unit_id, seq=k),
            "dataset_id": dataset_id,
            "unit_id": unit_id,
            "t_end": float(t_end),
            "domain": domain,
            "split": split,
        })
    return rows
